      "content": "{\n  \"name\": \"dsh-our-free-model\",\n  \"version\": \"2.8.3\",\n  \"private\": true,\n  \"type\": \"module\",\n  \"description\": \"Our Free Model — 在 dsh 里装上这个插件即可，无需登录、注册或填 API Key，就能使用包括 DeepSeek V4.1 Flash、Kimi K3 在内的前沿模型，桌面端另有 EAC 协付渠道；2.0 起接入 LobsterAI、Qoder、TRAE、Cline、Loomy、Raccoon、MiniMax、ZCode、Gemini 十个账号渠道（原有匿名免费通道保留）（登录、账号池、积分领取、本地 OpenAI 网关与局域网转发、数据看板与运行日志），六页毛玻璃界面统一呈现。\",\n  \"repository\": {\n    \"type\": \"git\",\n    \"url\": \"git+https://github.com/Ebony-Vinyl/dsh-our-free-model.git\"\n  },\n  \"homepage\": \"https://github.com/Ebony-Vinyl/dsh-our-free-model\",\n  \"bugs\": {\n    \"url\": \"https://github.com/Ebony-Vinyl/dsh-our-free-model/issues\"\n  },\n  \"main\": \"./index.js\",\n  \"exports\": {\n    \".\": \"./index.js\",\n    \"./client\": \"./client.js\",\n    \"./package.json\": \"./package.json\",\n    \"./locale/*.json\": \"./locale/*.json\"\n  },\n  \"scripts\": {\n    \"pack:standalone\": \"node scripts/pack-standalone.mjs\",\n    \"test:package\": \"node scripts/standalone-package-test.mjs\",\n    \"start:standalone\": \"node packages/standalone/cli.mjs\",\n    \"test:standalone\": \"node scripts/standalone-test.mjs\",\n    \"test:management\": \"node scripts/standalone-management-test.mjs\",\n    \"build:standalone-channels\": \"node scripts/build-standalone-channels.mjs\",\n    \"build:standalone-ui\": \"node scripts/build-standalone-ui.mjs\",\n    \"build:magpie\": \"node scripts/build-magpie-engine.mjs\",\n    \"update:magpie\": \"node scripts/update-magpie-engine.mjs\",\n    \"typecheck:standalone\": \"npm --prefix packages/standalone run typecheck\",\n    \"test:standalone-channels\": \"node scripts/standalone-channels-test.mjs\",\n    \"test\": \"node scripts/test-all.mjs\",\n    \"test:contributor\": \"node scripts/test-all.mjs --mode contributor\",\n    \"test:release\": \"node scripts/test-all.mjs --mode release\",\n    \"manifest\": \"node scripts/build-manifest.mjs\",\n    \"channel-pack\": \"node scripts/build-channel-pack.mjs\",\n    \"manifest:check\": \"node scripts/build-manifest.mjs --check\",\n    \"selftest\": \"node scripts/host-selftest.mjs\",\n    \"typecheck\": \"tsc --noEmit -p tsconfig.json\",\n    \"build:legacy-payload\": \"node scripts/build-legacy-payload.mjs\"\n  },\n  \"files\": [\n    \"index.js\",\n    \"client.js\",\n    \"adapter\",\n    \"src/adapter.js\",\n    \"src/aggregate.js\",\n    \"src/anthropic.js\",\n    \"src/bun-fetch.js\",\n    \"src/catalog.js\",\n    \"src/chan-relay.js\",\n    \"src/channel.js\",\n    \"src/combos.js\",\n    \"src/deferred-response.js\",\n    \"src/disclaimer.js\",\n    \"src/eac-login.js\",\n    \"src/eac-user.js\",\n    \"src/eac.js\",\n    \"src/effort.js\",\n    \"src/egress.js\",\n    \"src/engine-payload.js\",\n    \"src/failure.js\",\n    \"src/feed.js\",\n    \"src/forward.js\",\n    \"src/gemini.js\",\n    \"src/http.js\",\n    \"src/image-pricing.js\",\n    \"src/kilo.js\",\n    \"src/local-optimize.js\",\n    \"src/loopback-fetch.js\",\n    \"src/magpie-engine.js\",\n    \"src/magpie-models.js\",\n    \"src/magpie-policy.js\",\n    \"src/messages.js\",\n    \"src/model-test.js\",\n    \"src/open-external.js\",\n    \"src/picks.js\",\n    \"src/probe.js\",\n    \"src/push.js\",\n    \"src/recovery.js\",\n    \"src/reload.js\",\n    \"src/semver.js\",\n    \"src/store.js\",\n    \"src/extensions.js\",\n    \"src/plugins.js\",\n    \"src/stream.js\",\n    \"src/subscription-adapter.js\",\n    \"src/subscription-completion.js\",\n    \"src/subscriptions.js\",\n    \"src/trust.js\",\n    \"src/updater.js\",\n    \"src/upstream.js\",\n    \"src/vault-anchor.js\",\n    \"src/vault-data.js\",\n    \"src/vault.js\",\n    \"src/token-saver.js\",\n    \"src/engine-parts\",\n    \"src/core.js\",\n    \"src/providers\",\n    \"src/route\",\n    \"src/o2a.js\",\n    \"vendor/channel-pack/pack.js\",\n    \"vendor/channel-pack/qoder-auth-wasm.wasm\",\n    \"vendor/channel-pack/NOTICE.md\",\n    \"vendor/channel-pack/LICENSE\",\n    \"locale\",\n    \"icon.svg\",\n    \"cordis.patch.yml\",\n    \"LICENSE\",\n    \"vendor/magpie/engine.json\",\n    \"vendor/magpie/LICENSE\",\n    \"vendor/magpie/NOTICE.md\"\n  ],\n  \"keywords\": [\n    \"dsh\",\n    \"dsh-plugin\",\n    \"free-model\",\n    \"llm-provider\"\n  ],\n  \"engines\": {\n    \"node\": \"^22.19.0 || >=24.0.0\"\n  },\n  \"dsh\": {\n    \"bundle\": {\n      \"patch\": \"./cordis.patch.yml\"\n    },\n    \"client\": {\n      \"platform\": \"web\",\n      \"immediately\": true,\n      \"inject\": []\n    }\n  },\n  \"license\": \"MIT\",\n  \"peerDependencies\": {\n    \"@deepseek-ai/cordis\": \"^4.0.2\",\n    \"@deepseek-ai/dsh-commands\": \"^0.1.2-rc.1 || ^0.1.7-rc.2 || ^0.2.0-rc.1\",\n    \"@deepseek-ai/dsh-credentials\": \"^0.1.2-rc.1 || ^0.1.7-rc.2 || ^0.2.0-rc.1\",\n    \"@deepseek-ai/dsh-llm\": \"^0.1.2-rc.1 || ^0.1.7-rc.2 || ^0.2.0-rc.1\",\n    \"@deepseek-ai/schemastery\": \"^3.18.4\"\n  },\n  \"devDependencies\": {\n    \"@gfx/zopfli\": \"^1.0.15\",\n    \"dsh-llm-legacy\": \"npm:@deepseek-ai/dsh-llm@0.1.5-rc.2\",\n    \"esbuild\": \"0.25.9\",\n    \"typescript\": \"^5.9.2\",\n    \"undici\": \"8.12.2\"\n  },\n  \"overrides\": {\n    \"dsh-llm-legacy\": {\n      \"@deepseek-ai/dsh-brand\": \"0.1.5-rc.2\",\n      \"@deepseek-ai/dsh-timeout\": \"0.1.5-rc.2\",\n      \"@deepseek-ai/dsh-typert-protocol\": \"0.1.5-rc.2\",\n      \"@deepseek-ai/dsh-util-crypto\": \"0.1.5-rc.2\",\n      \"@deepseek-ai/dsh-util-values\": \"0.1.5-rc.2\"\n    }\n  }\n}\n"
